<?php require __DIR__.'/_init.php';$keys=['hero_title'=>'تیتر صفحه اصلی','hero_subtitle'=>'زیرتیتر صفحه اصلی','contact_phone'=>'شماره تماس','contact_email'=>'ایمیل پشتیبانی','shipping_fee'=>'هزینه ارسال (تومان)','free_shipping_threshold'=>'ارسال رایگان از مبلغ (تومان)','about_text'=>'متن درباره ما'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($keys as $key=>$label){$val=trim((string)($_POST[$key]??''));$q=$pdo->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$q->execute([$key,$val]);}flash('success','تنظیمات ذخیره شد.');header('Location: '.site_url('admin/settings.php'));exit;}render_header('تنظیمات سایت');?><main class="container"><div class="page-title"><h1>تنظیمات سایت</h1><p>محتوای اصلی، اطلاعات تماس و قوانین ارسال را مدیریت کنید.</p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('admin/index.php'))?>">داشبورد</a><a href="<?=e(site_url('admin/products.php'))?>">محصولات</a><a href="<?=e(site_url('admin/orders.php'))?>">سفارش‌ها</a><a href="<?=e(site_url('admin/print-options.php'))?>">گزینه‌های چاپ</a><a href="<?=e(site_url('admin/coupons.php'))?>">کدهای تخفیف</a></aside><section class="admin-content"><div class="form-card"><form method="post"><?=csrf_field()?><?php foreach($keys as $key=>$label):?><div class="form-group"><label><?=e($label)?></label><?php if(in_array($key,['hero_subtitle','about_text'])):?><textarea name="<?=e($key)?>" rows="4"><?=e(setting($key))?></textarea><?php else:?><input name="<?=e($key)?>" value="<?=e(setting($key))?>" <?=in_array($key,['shipping_fee','free_shipping_threshold'])?'type="number" min="0"':''?> ><?php endif;?></div><?php endforeach;?><button class="btn">ذخیره تنظیمات</button></form></div></section></div></main><?php render_footer();?>
